6	/**
7	 * Parses Prometheus metrics text and extracts sum and count for each endpoint.
8	 * Returns an object with two maps: sum and count, keyed by endpoint string.
9	 */
10	export function parsePrometheusMetrics(text: string): {
11	  sum: Record<string, number>;
12	  count: Record<string, number>;
13	} {
14	  const lines = text.split('\n');
15	  const sum: Record<string, number> = {};
16	  const count: Record<string, number> = {};
17	
18	  for (const line of lines) {
19	    const trimmed = line.trim();
20	    // Example: martin_http_requests_duration_seconds_sum{endpoint="/sprite/{source_ids}.json",method="GET",status="200"} 123.456
21	    let match = trimmed.match(
22	      /^martin_http_requests_duration_seconds_sum\{(.*)\}\s+([0-9.eE+-]+)$/,
23	    );
24	    if (match) {
25	      const labels = match[1];
26	      const value = parseFloat(match[2]);
27	      const endpoint = /endpoint="([^"]+)"/.exec(labels)?.[1];
28	
29	      if (endpoint) sum[endpoint] = (sum[endpoint] || 0) + value;
30	      continue;
31	    }
32	    match = trimmed.match(/^martin_http_requests_duration_seconds_count\{(.*)\}\s+([0-9.eE+-]+)$/);
33	    if (match) {
34	      const labels = match[1];
35	      const value = parseFloat(match[2]);
36	      const endpoint = /endpoint="([^"]+)"/.exec(labels)?.[1];
37	      if (endpoint) count[endpoint] = (count[endpoint] || 0) + value;
38	    }
39	  }
40	  return { count, sum };
41	}
