72	/**
73	 * Parses Prometheus histogram metrics and extracts bucket data for each endpoint.
74	 * Returns an object mapping endpoint strings to histogram data.
75	 */
76	export function parsePrometheusHistogram(text: string): Record<string, HistogramBucket[]> {
77	  const lines = text.split('\n');
78	  const histograms: Record<string, HistogramBucket[]> = {};
79	
80	  for (const line of lines) {
81	    const trimmed = line.trim();
82	
83	    // Parse bucket lines: martin_http_requests_duration_seconds_bucket{...le="0.1"} 123
84	    const match = trimmed.match(
85	      /^martin_http_requests_duration_seconds_bucket\{(.*)\}\s+([0-9.eE+-]+)$/,
86	    );
87	    if (match) {
88	      const labels = match[1];
89	      const count = parseFloat(match[2]);
90	      const endpoint = /endpoint="([^"]+)"/.exec(labels)?.[1];
91	      const leMatch = /le="([^"]+)"/.exec(labels);
92	
93	      if (endpoint && leMatch) {
94	        const le = leMatch[1] === '+Inf' ? Infinity : parseFloat(leMatch[1]);
95	
96	        if (!histograms[endpoint]) {
97	          histograms[endpoint] = [];
98	        }
99	
100	        // Skip +Inf bucket as it's redundant with count
101	        if (le !== Infinity) {
102	          histograms[endpoint].push({ count, le });
103	        }
104	      }
105	    }
106	  }
107	
108	  // Sort buckets by le value for each endpoint
109	  for (const histogram of Object.values(histograms)) {
110	    histogram.sort((a, b) => a.le - b.le);
111	  }
112	
113	  return histograms;
114	}
115	
116	/**
117	 * Parses complete Prometheus metrics including sum, count, and histogram data.
118	 * Returns an object with all three types of metrics for comprehensive analysis.
119	 */
120	export function parseCompletePrometheusMetrics(text: string): {
121	  sum: Record<string, number>;
122	  count: Record<string, number>;
123	  histograms: Record<string, HistogramBucket[]>;
124	} {
125	  return {
126	    ...parsePrometheusMetrics(text),
127	    histograms: parsePrometheusHistogram(text),
128	  };
129	}
